    loss_p = int(assign.get('loss_p'))
    tie_p = int(assign.get('tie_p'))
    min_points = int(assign.get('min_points'))
except Exception:
    return (False, None)  # invalid types

# Basic checks
if matches < 10:
    return (False, None)  # ensure sufficient hardness via larger state space
if den <= 0:
    return (False, None)
if win_p <= 0 or loss_p <= 0 or tie_p <= 0:
    return (False, None)  # avoid degeneracies
if win_p != loss_p:
    return (False, None)  # symmetry required by the family
if win_p + loss_p + tie_p != den:
    return (False, None)
if not (0 <= min_points <= 3 * matches):
    return (False, None)

p = Fraction(win_p, den)
q = p
r = Fraction(tie_p, den)
# compute probability
