ans = Fraction(0, 1)
for t in range(0, n + 1):
    w_min = (n - t) // 2 + 1  # strict inequality w > l
    if w_min < 0:
        w_min = 0
    for w in range(w_min, n - t + 1):
        l = n - w - t
        if l < 0:
            continue
