        if points >= min_points:
            ways = comb(n, w) * comb(n - w, l)
            ans += Fraction(ways, 1) * (p ** w) * (q ** l) * (r ** t)

# Validity and hardness checks
if ans <= 0 or ans >= 1:
    return (False, None)  # trivial or invalid probability
# Enforce nontriviality band
f = float(ans)
